sys_script_client.script:
function onLoad() {
    var patientId = g_form.getValue('u_patient_id'); // Reference field

    if (!patientId) return;

    var ga = new GlideAjax('PatientUtilsClient');
    ga.addParam('sysparm_name', 'getPatientDetails');
    ga.addParam('sysparm_patient_id', patientId);

    ga.getXMLAnswer(function(response) {
        if (response) {
            var data = JSON.parse(response);

            var message = 'Patient Info:\n' +
                          'Name: ' + data.first_name + ' ' + data.last_name + '\n' +
                          'Gender: ' + data.gender


            g_form.addInfoMessage(message); // OR use alert(message);
        }
    });
}
